static AVRational rational(const char *s){AVRational r;sscanf(s,"%d/%d",&r.num,&r.den);return r;}
int main(int argc,char **argv){if(argc!=8)return 2;av_log_set_level(AV_LOG_QUIET);OutputFilterPriv ofp={0};AVFrame frame={0};ofp.ofilter.type=AVMEDIA_TYPE_VIDEO;ofp.fps.vsync_method=!strcmp(argv[1],"cfr")?VSYNC_CFR:!strcmp(argv[1],"vscfr")?VSYNC_VSCFR:!strcmp(argv[1],"vfr")?VSYNC_VFR:VSYNC_PASSTHROUGH;frame_data.dec.tb=rational(argv[6]);ofp.fps.framerate_max=rational(argv[7]);sink_rate=rational(argv[2]);frame.time_base=rational(argv[3]);ofp.fps.framerate=rational(argv[4]);ofp.enc_timebase=rational(argv[5]);int ret=choose_out_timebase(&ofp,&frame);printf("{\"ret\":%d,\"frameRate\":{\"num\":%d,\"den\":%d},\"timeBase\":{\"num\":%d,\"den\":%d}}\n",ret,ofp.fps.framerate.num,ofp.fps.framerate.den,ofp.tb_out.num,ofp.tb_out.den);return 0;}
